/**
 * Upstream URLs are generated by the cluster for the cluster's own network, not for the browser:
 *
 *  - the ResourceManager advertises itself by hostname (`http://rm-host:8088/proxy/<app>/…`, seen live as
 *    `http://smadayma:8088/proxy/…`) — a browser that reaches Burrow over a tunnel or from another host cannot
 *    resolve that name;
 *  - NodeManagers advertise their own node address (`http://127.0.0.3:8042/node/containerlogs/…`);
 *  - JobHistory/Spark History advertise whichever host they were configured with.
 *
 * The operator told Burrow where those daemons really are (`--rm`, `--jhs`, `--spark-history`, or Hadoop conf
 * discovery), so any outbound link is rewritten to the configured base for the daemon it points at. The raw upstream
 * value is never touched — it stays in `data-yv` for the parity harness — only the link target is corrected.
 *
 * NodeManager pages are the one case we cannot proxy: Burrow exposes NM *REST* under `/api/nm/…` but not the NM's
 * HTML UI, so those links are left exactly as the RM reported them and flagged with `internal: true` so the UI can
 * say "reachable from the cluster network" instead of pretending it will open.
 */

import { useQuery } from "@tanstack/react-query";
import { q } from "~/api/queries";

export interface UpstreamBases {
  /** e.g. `http://127.0.0.1:8088` — the manager's own configured base */
  rm?: string | null;
  sparkHistory?: string | null;
  jhs?: string | null;
}

export interface RewrittenUrl {
  /** the link target (rewritten when we know a better base, otherwise the original) */
  href: string;
  /** true when the URL points at a daemon only reachable from the cluster network (NM HTML) */
  internal: boolean;
  /** which daemon the URL belongs to, for labels/tooltips */
  kind: "rm" | "rm-proxy" | "spark-history" | "jhs" | "node-manager" | "other";
  /** the original upstream value, unchanged */
  raw: string;
}

const CONTAINER_LOGS = /\/node\/containerlogs\//;
const NM_REST = /^\/ws\/v1\/node\//;

function parse(url: string): URL | null {
  try {
    return new URL(url);
  } catch {
    return null;
  }
}

function originOf(base: string | null | undefined): string | null {
  if (!base) return null;
  const u = parse(base);
  return u ? u.origin : null;
}

function sameOrigin(a: string, b: string | null | undefined): boolean {
  const bo = originOf(b);
  if (!bo) return false;
  const u = parse(a);
  return !!u && u.origin === bo;
}

/**
 * Classify an upstream URL and, where Burrow knows a browser-reachable base for that daemon, rewrite it.
 * Ports are used as the fallback signal because the hosts differ between what the cluster advertises and what the
 * operator configured.
 */
export function rewriteUpstreamUrl(url: string | null | undefined, bases: UpstreamBases = {}): RewrittenUrl {
  const raw = url ?? "";
  const fallback: RewrittenUrl = { href: raw, internal: false, kind: "other", raw };
  if (!raw) return fallback;
  const u = parse(raw);
  if (!u) return fallback;

  const rmOrigin = originOf(bases.rm);
  const shsOrigin = originOf(bases.sparkHistory);
  const jhsOrigin = originOf(bases.jhs);

  const rmPort = rmOrigin ? parse(rmOrigin)?.port : null;
  const jhsPort = jhsOrigin ? parse(jhsOrigin)?.port : null;

  if (CONTAINER_LOGS.test(u.pathname) || NM_REST.test(u.pathname) || u.port === "8042") {
    // NodeManager HTML: we cannot proxy it (Burrow exposes NM REST only), so the link is honest about that.
    return { href: raw, internal: true, kind: "node-manager", raw };
  }
  if (u.pathname.includes("/jobhistory/") || (jhsPort && u.port === jhsPort)) {
    const href = jhsOrigin ? jhsOrigin + u.pathname + u.search + u.hash : raw;
    return { href, internal: false, kind: "jhs", raw };
  }
  if (u.pathname.startsWith("/proxy/")) {
    const href = rmOrigin ? rmOrigin + u.pathname + u.search + u.hash : raw;
    return { href, internal: false, kind: "rm-proxy", raw };
  }
  if (u.pathname.startsWith("/cluster/") || u.pathname === "/conf" || u.pathname === "/jmx" || u.pathname === "/stacks") {
    const href = rmOrigin ? rmOrigin + u.pathname + u.search + u.hash : raw;
    return { href, internal: false, kind: "rm", raw };
  }
  if (shsOrigin && sameOrigin(raw, bases.sparkHistory)) {
    return { href: raw, internal: false, kind: "spark-history", raw };
  }
  if (rmPort && (u.port === rmPort || u.pathname.startsWith("/ws/v1/cluster/"))) {
    const href = rmOrigin ? rmOrigin + u.pathname + u.search + u.hash : raw;
    return { href, internal: false, kind: "rm", raw };
  }
  return fallback;
}

/**
 * The RM's own web-proxy URL for an application (`http://<rm>/proxy/<appId>/`), from the configured base. The RM's
 * page links every live app this way even when the REST payload omits `trackingUrl`; Burrow cannot echo the RM's
 * advertised hostname (it lives for the cluster's network, not the browser), so the operator-configured base is used.
 */
export function rmProxyUrl(appId: string, bases: UpstreamBases = {}): string | null {
  const origin = originOf(bases.rm);
  return origin ? `${origin}/proxy/${appId}/` : null;
}

/** The operator-configured daemon bases, from `/api/meta` — used by every outbound-link call site. */
export function useUpstreamBases(): UpstreamBases {
  const meta = useQuery(q.meta());
  return {
    rm: meta.data?.rm?.active ?? null,
    sparkHistory: meta.data?.services?.sparkHistory?.url ?? null,
    jhs: meta.data?.services?.jobHistory?.url ?? null,
  };
}
